var i=`0377-stoemp`;var n=`world-0377`;var o=`BE`;var s=`western-europe`;var a=4;var l=32;var r={en:`Stoemp`,ua:`Стумп`};var d={en:`A traditional Belgium dish made with potato, carrot, leek, whole cow milk. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Бельгія. Основні інгредієнти: картопля, морква, цибуля-порей, цільне коров'яче молоко. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var m=[{en:`Cook the listed ingredients in simmering water for about 24 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 24 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:24,i:[[`potato`,850,`g`],[`carrot`,260,`g`],[`leek`,230,`g`],[`water`,900,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`unsalted-butter`,110,`g`],[`whole-cow-milk`,180,`ml`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`parsley`,17,`g`]]}];var g={slug:i,id:n,country:`BE`,region:s,servings:4,minutes:32,title:r,text:d,steps:m};export{o as country,g as default,n as id,l as minutes,s as region,a as servings,i as slug,m as steps,d as text,r as title};